  "ui.placeLocal": ["Local spirit: {name}", "Yerel ruh: {name}", "เพื่อนตลาดประจำที่: {name}"], "ui.stamps": ["Stamps", "Damgalar", "ตราประทับ"], "ui.stormTag": ["Storm {n}", "Fırtına {n}", "พายุ {n}"], "ui.stormTitle": ["Storm level", "Fırtına seviyesi", "ระดับพายุ"], "ui.stormOff": ["Off", "Kapalı", "ปิด"],
